func TestDenialFieldsAndContext(t *testing.T) {
	loader := mapRoleLoader{
		1: {ID: 1, Name: "reader", IsActive: true, Access: []model.RoleAccess{rule("*", "*", model.VerbGet)}},
	}
	enf := NewEnforcer(loader)
	p := &Principal{Type: PrincipalAPIKey, KeyID: 9, RoleID: 1}

	err := enf.Authorize(context.Background(), p, "mydb", "/_table/items/", model.VerbDelete)
	var d *Denial
	if !errors.As(err, &d) {
		t.Fatalf("expected Denial, got %v", err)
	}
	if d.Role != "reader" {
		t.Errorf("Role = %q, want reader", d.Role)
	}
	if d.Service != "mydb" {
		t.Errorf("Service = %q, want mydb", d.Service)
	}
	if d.Component != "_table/items" {
		t.Errorf("Component = %q, want _table/items (normalized)", d.Component)
	}
	if d.Verb != model.VerbDelete {
		t.Errorf("Verb = %d, want %d", d.Verb, model.VerbDelete)
	}
	if d.Error() == "" || d.Error() != d.Reason {
		t.Errorf("Error() = %q, want Reason %q", d.Error(), d.Reason)
	}

	ctx := d.Context()
	want := map[string]interface{}{
		"role":      "reader",
		"service":   "mydb",
		"component": "_table/items",
		"verb":      "DELETE",
	}
	if !reflect.DeepEqual(ctx, want) {
		t.Errorf("Context() = %v, want %v", ctx, want)
	}
}

func TestDenialContext_OmitsEmptyFields(t *testing.T) {
	d := &Denial{Reason: "nope"}
	if got := d.Context(); len(got) != 0 {
		t.Errorf("expected empty context for bare Denial, got %v", got)
	}

	d = &Denial{Reason: "nope", Service: "mydb", Verb: model.VerbGet | model.VerbPost}
	got := d.Context()
	if got["service"] != "mydb" {
		t.Errorf("service = %v, want mydb", got["service"])
	}
	if got["verb"] != "GET,POST" {
		t.Errorf("verb = %v, want GET,POST", got["verb"])
	}
	if _, ok := got["role"]; ok {
		t.Error("role should be omitted when empty")
	}
	if _, ok := got["component"]; ok {
		t.Error("component should be omitted when empty")
	}
}

package server

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// The admin UI and the MCP endpoint share /mcp. Browsers must get the page;
// MCP clients must reach the MCP handler (which requires auth).
func TestMCPPathSharedWithUI(t *testing.T) {
	env := newTestEnv(t)

	get := func(accept string) *httptest.ResponseRecorder {
		req := httptest.NewRequest(http.MethodGet, "/mcp", nil)
		if accept != "" {
			req.Header.Set("Accept", accept)
		}
		rr := httptest.NewRecorder()
		env.server.Router().ServeHTTP(rr, req)
		return rr
	}

	browser := get("text/html,application/xhtml+xml,*/*;q=0.8")
	if ct := browser.Header().Get("Content-Type"); browser.Code == http.StatusOK && !strings.HasPrefix(ct, "text/html") {
		t.Errorf("browser navigation: got %d %q, want the UI page", browser.Code, ct)
	}

	for _, accept := range []string{"text/event-stream", "application/json, text/event-stream", ""} {
		rr := get(accept)
		if strings.HasPrefix(rr.Header().Get("Content-Type"), "text/html") {
			t.Errorf("Accept %q: got the UI page, want the MCP handler", accept)
		}
		if rr.Code != http.StatusUnauthorized {
			t.Errorf("Accept %q: status %d, want 401 from MCP auth", accept, rr.Code)
		}
	}
}

package service

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"sync"
	"time"

	"github.com/golang-jwt/jwt/v5"

	"github.com/faucetdb/faucet/internal/config"
)

var (
	ErrInvalidCredentials = errors.New("invalid credentials")
	ErrTokenExpired       = <REDACTED>"token expired")
	ErrKeyRevoked         = errors.New("api key revoked")
)

type APIKeyPrincipal struct {
	KeyID  int64
	RoleID int64
}

type JWTPrincipal struct {
	AdminID int64
	Email   string
}

// LastUsedInterval is the minimum time between two last_used writes for
// the same API key. ValidateAPIKey is on the hot path of every API-key
// request and the config store runs on a single SQLite connection, so
// persisting last_used on every call would compete with the RBAC reads
// each request also needs. It is a variable so tests can shorten it.
var LastUsedInterval = 60 * time.Second

type AuthService struct {
	store     *config.Store
	jwtSecret []byte

	lastUsedMu sync.Mutex
	lastUsed   map[int64]time.Time // key ID -> time of last persisted last_used write
}

func NewAuthService(store *config.Store, jwtSecret string) *AuthService {
	return &AuthService{
		store:     store,
		jwtSecret: <REDACTED>
		lastUsed:  make(map[int64]time.Time),
	}
}

// ValidateAPIKey checks the provided raw API key against stored key hashes.
func (s *AuthService) ValidateAPIKey(ctx context.Context, rawKey string) (*APIKeyPrincipal, error) {
	hash := hashKey(rawKey)

	key, err := s.store.GetAPIKeyByHash(ctx, hash)
	if err != nil {
		return nil, ErrInvalidCredentials
	}

	if !key.IsActive {
		return nil, ErrKeyRevoked
	}

	if key.ExpiresAt != nil && key.ExpiresAt.Before(time.Now()) {
		return nil, ErrTokenExpired
	}

	s.touchLastUsed(key.ID)

	return &APIKeyPrincipal{
		KeyID:  key.ID,
		RoleID: key.RoleID,
	}, nil
}

// touchLastUsed persists the key's last_used timestamp, but at most once
// per LastUsedInterval per key. The write is fire-and-forget: it never
// blocks or fails the request, and a lost write only makes last_used
// slightly stale.
func (s *AuthService) touchLastUsed(keyID int64) {
	now := time.Now()

	s.lastUsedMu.Lock()
	if last, ok := s.lastUsed[keyID]; ok && now.Sub(last) < LastUsedInterval {
		s.lastUsedMu.Unlock()
		return
	}
	s.lastUsed[keyID] = now
	s.lastUsedMu.Unlock()

	go s.store.UpdateAPIKeyLastUsed(context.Background(), keyID) //nolint:errcheck
}

// ValidateJWT verifies a JWT bearer token and returns the associated admin identity.
func (s *AuthService) ValidateJWT(ctx context.Context, tokenStr string) (*JWTPrincipal, error) {
	claims := &jwtClaims{}

	token, err := jwt.ParseWithClaims(tokenStr, claims, func(token *jwt.Token) (interface{}, error) {
		if _, ok := token.Method.(*jwt.SigningMethodHMAC); !ok {
			return nil, errors.New("unexpected signing method")
		}
		return s.jwtSecret, nil
	})
	if err != nil {
		return nil, ErrInvalidCredentials
	}

	if !token.Valid {
		return nil, ErrInvalidCredentials
	}

	return &JWTPrincipal{
		AdminID: claims.AdminID,
		Email:   claims.Email,
	}, nil
}

// IssueJWT creates a new signed JWT token for the given admin.
func (s *AuthService) IssueJWT(ctx context.Context, adminID int64, email string, ttl time.Duration) (string, error) {
	now := time.Now()
	claims := jwtClaims{
		AdminID: adminID,
		Email:   email,
		RegisteredClaims: jwt.RegisteredClaims{
			IssuedAt:  jwt.NewNumericDate(now),
			ExpiresAt: jwt.NewNumericDate(now.Add(ttl)),
			Issuer:    "faucet",
		},
	}

	token :<REDACTED> jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
	return token.SignedString(s.jwtSecret)
}

type jwtClaims struct {
	AdminID int64  `json:"admin_id"`
	Email   string `json:"email"`
	jwt.RegisteredClaims
}

func hashKey(rawKey string) string {
	h := sha256.Sum256([]byte(rawKey))
	return hex.EncodeToString(h[:])
}

package cli

import (
	"bytes"
	"context"
	"encoding/hex"
	"log/slog"
	"strings"
	"testing"

	"github.com/spf13/viper"

	"github.com/faucetdb/faucet/internal/config"
)

func resetViper(t *testing.T) {
	t.Helper()
	viper.Reset()
	t.Cleanup(viper.Reset)
}

func TestResolveJWTSecret_ViperValueWins(t *testing.T) {
	resetViper(t)
	viper.Set("auth.jwt_secret", "configured-secret")

	store, err := config.NewStore("")
	if err != nil {
		t.Fatalf("NewStore: %v", err)
	}
	defer store.Close()
	// A different stored value must be ignored when config/env is set.
	if err := store.SetSetting(context.Background(), jwtSecretSettingKey, "stored-secret"); err != nil {
		t.Fatalf("SetSetting: %v", err)
	}

	got, err := resolveJWTSecret(context.Background(), store, nil)
	if err != nil {
		t.Fatalf("resolveJWTSecret: <REDACTED>", err)
	}
	if got != "configured-secret" {
		t.Errorf("got %q, want configured value", got)
	}
}

func TestResolveJWTSecret_EnvAliases(t *testing.T) {
	for _, name := range []string{"FAUCET_AUTH_JWT_SECRET", "FAUCET_JWT_SECRET"} {
		t.Run(name, func(t *testing.T) {
			resetViper(t)
			t.Setenv("FAUCET_AUTH_JWT_SECRET", "")
			t.Setenv("FAUCET_JWT_SECRET", "")
			t.Setenv(name, "from-"+name)
			initConfig()

			store, err := config.NewStore("")
			if err != nil {
				t.Fatalf("NewStore: %v", err)
			}
			defer store.Close()

			got, err := resolveJWTSecret(context.Background(), store, nil)
			if err != nil {
				t.Fatalf("resolveJWTSecret: <REDACTED>", err)
			}
			if got != "from-"+name {
				t.Errorf("got %q, want value from %s", got, name)
			}
		})
	}
}

func TestResolveJWTSecret_GeneratedAndPersisted(t *testing.T) {
	resetViper(t)
	t.Setenv("FAUCET_AUTH_JWT_SECRET", "")
	t.Setenv("FAUCET_JWT_SECRET", "")

	store, err := config.NewStore("")
	if err != nil {
		t.Fatalf("NewStore: %v", err)
	}
	defer store.Close()

	var buf bytes.Buffer
	logger := slog.New(slog.NewTextHandler(&buf, nil))

	first, err := resolveJWTSecret(context.Background(), store, logger)
	if err != nil {
		t.Fatalf("first resolveJWTSecret: <REDACTED>", err)
	}
	if first == "" || first == "faucet-dev-secret-change-me" {
		t.Fatalf("expected a generated secret, got %q", first)
	}
	raw, err := hex.DecodeString(first)
	if err != nil || len(raw) != jwtSecretBytes {
		t.Errorf("secret should be %d hex-encoded random bytes, got %q (err=%v)", jwtSecretBytes, first, err)
	}
	if !strings.Contains(buf.String(), "generated a new JWT signing secret") {
		t.Errorf("expected INFO log about generation, got %q", buf.String())
	}

	stored, err := store.GetSetting(context.Background(), jwtSecretSettingKey)
	if err != nil {
		t.Fatalf("GetSetting: %v", err)
	}
	if stored != first {
		t.Errorf("persisted secret %q != returned %q", stored, first)
	}

	buf.Reset()
	second, err := resolveJWTSecret(context.Background(), store, logger)
	if err != nil {
		t.Fatalf("second resolveJWTSecret: <REDACTED>", err)
	}
	if second != first {
		t.Errorf("secret not stable across calls: %q vs %q", first, second)
	}
	if strings.Contains(buf.String(), "generated") {
		t.Errorf("second call should not generate again, got log %q", buf.String())
	}

	// Two independent stores generate different secrets.
	other, err := config.NewStore("")
	if err != nil {
		t.Fatalf("NewStore: %v", err)
	}
	defer other.Close()
	third, err := resolveJWTSecret(context.Background(), other, nil)
	if err != nil {
		t.Fatalf("resolveJWTSecret on other store: %v", err)
	}
	if third == first {
		t.Error("two stores produced the same generated secret")
	}
}

func TestResolveJWTSecret_NilStore(t *testing.T) {
	resetViper(t)
	t.Setenv("FAUCET_AUTH_JWT_SECRET", "")
	t.Setenv("FAUCET_JWT_SECRET", "")
	if _, err := resolveJWTSecret(context.Background(), nil, nil); err == nil {
		t.Error("expected error with nil store and no configured secret")
	}
}

